import 'dart:io'; void main() { var f = File('lib/screens/log_list_page.dart'); var s = f.readAsStringSync(); var target = '''Expanded(\n                        child: Text(\n                          log['program']?.toString() ?? '',\n                          style: TextStyle(color: (Theme.of(context).textTheme.bodyLarge?.color ?? Colors.white).withOpacity(0.7), fontSize: lay.programFontSize),\n                          maxLines: 1,\n                          overflow: TextOverflow.ellipsis,\n                        ),\n                      ),'''; var replacement = '''Expanded(\n                        child: Row(\n                          mainAxisSize: MainAxisSize.min,\n                          children: [\n                            Flexible(\n                              child: Text(\n                                log['program']?.toString() ?? '',\n                                style: TextStyle(color: (Theme.of(context).textTheme.bodyLarge?.color ?? Colors.white).withOpacity(0.7), fontSize: lay.programFontSize),\n                                maxLines: 1,\n                                overflow: TextOverflow.ellipsis,\n                              ),\n                            ),\n                            if (_hasLogError(log)) const Padding(padding: EdgeInsets.only(left: 4), child: Icon(Icons.warning_amber_rounded, color: Colors.redAccent, size: 14)),\n                          ],\n                        ),\n                      ),'''; s = s.replaceAll(target, replacement); f.writeAsStringSync(s); print('done'); }
